'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {spawn}=require('node:child_process'),{once}=require('node:events');
const Q=require('/workspace/project-dollers/qa/team-details/qa.cjs');
const ROOT=Q.ROOT,sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const before=Q.runtimeManifest(),manifestPath=ROOT+'/qa/team-details/candidate-runtime-manifest.json';
const manifestSha=sha(fs.readFileSync(manifestPath));
assert.equal(manifestSha,'fe69378eb4a1fb9d7e766788b80410b6b568c834359bc9805c802820ed5d2e01');
assert.deepEqual(JSON.parse(fs.readFileSync(manifestPath)),before);
const snapshot=JSON.parse(fs.readFileSync(ROOT+'/assets/data/team-details.json'));
const fixtureDir=fs.mkdtempSync('/workspace/recovery-qa/team-details/refresh-integration-');
const sourceFile=fixtureDir+'/snapshot.json',stateFile=fixtureDir+'/server-state.json',logFile=fixtureDir+'/http-fixture.jsonl';
const report={status:'running',startedAt:new Date().toISOString(),qualification:'Isolated natural HTTP fixture integration of the exact production module. The server deliberately substitutes ONLY its own local team-data endpoint with marked test fixtures; these values are not current football truth, actual hosted evidence or independent provider verification. Actual repository/runtime/source data remain untouched. No Playwright routing, browser TLS bypass or injected application code.',source:{manifestSha256:manifestSha,runtimeFiles:before,moduleSha256:before['assets/team-details.js'],realDataSha256:sha(fs.readFileSync(ROOT+'/assets/data/team-details.json')),testModuleSha256:sha(fs.readFileSync(__filename)),fixtureServerSha256:sha(fs.readFileSync('/workspace/recovery-qa/team-details/refresh-fixture-server.py'))},fixtureDirectory:fixtureDir,cases:[]};
function fixture(value,status=200){fs.writeFileSync(sourceFile,JSON.stringify(value));fs.writeFileSync(stateFile,JSON.stringify({body:sourceFile,status}));}
fixture(snapshot);
let server,browser,page;
(async()=>{try{
 const port=await Q.freePort(),base=`http://127.0.0.1:${port}/project-dollers/`;
 server=spawn('python3',['-u','/workspace/recovery-qa/team-details/refresh-fixture-server.py','--port',String(port),'--state',stateFile,'--logs',logFile],{stdio:['ignore','ignore','pipe']});
 let serverError='';server.stderr.on('data',b=>serverError+=b);let ready=false;
 for(let i=0;i<40;i++){try{if((await fetch(base)).status===200){ready=true;break;}}catch{}await Q.WAIT(100);}assert.ok(ready,serverError);report.base=base;
 browser=await Q.launch('chromium',false);report.browserVersion=browser.version();
 const context=await browser.newContext({viewport:{width:393,height:852},deviceScaleFactor:2,isMobile:true,hasTouch:true});
 page=await context.newPage();const errors=[],responseErrors=[],failed=[];
 page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.status()>=400)responseErrors.push({url:r.url(),status:r.status()});});page.on('requestfailed',r=>failed.push({url:r.url(),error:r.failure()}));
 assert.equal((await page.goto(base+'#team/DAL',{waitUntil:'networkidle'})).status(),200);await Q.ready(page);await Q.active(page);
 assert.deepEqual(await page.evaluate(()=>window.PDTeamDetails.getDataset()),snapshot);
 await page.waitForFunction(()=>!!document.querySelector('.td-hero .td-frame-glints')?.getAnimations().length);
 const refresh=()=>page.locator('[data-page="team-details"] .td-footer [data-td-action="refresh"]');
 await refresh().focus();
 await page.evaluate(()=>{
  const root=document.querySelector('[data-page="team-details"]'),glints=root.querySelector('.td-hero .td-frame-glints');
  window.__pdRefreshFixtureAudit={root,hero:root.querySelector('.td-hero'),button:root.querySelector('.td-footer [data-td-action="refresh"]'),animation:glints.getAnimations()[0],events:[]};
  const m=window.__pdRefreshFixtureAudit;m.startTime=m.animation.startTime;m.currentTime=m.animation.currentTime;
  document.addEventListener('pd:team-data-ready',e=>m.events.push(e.detail));
 });
 async function refreshNative(expectedStatus=200){
  const response=page.waitForResponse(r=>r.url()===base+'assets/data/team-details.json'&&r.request().method()==='GET');
  await refresh().tap();assert.equal((await response).status(),expectedStatus);
  await page.waitForFunction(()=>document.querySelector('[data-page="team-details"] .td-footer [data-td-action="refresh"]')?.getAttribute('aria-busy')==='false');
  await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
 }
 await refreshNative();
 const same=await page.evaluate(()=>{const m=window.__pdRefreshFixtureAudit;return{heroSame:m.hero===m.root.querySelector('.td-hero'),buttonSame:m.button===m.root.querySelector('.td-footer [data-td-action="refresh"]'),focusSame:document.activeElement===m.button,animationSame:m.animation===m.root.querySelector('.td-hero .td-frame-glints').getAnimations()[0],startTimeSame:m.animation.startTime===m.startTime,currentTimeBefore:m.currentTime,currentTimeAfter:m.animation.currentTime,event:m.events.at(-1)};});
 for(const field of ['heroSame','buttonSame','focusSame','animationSame','startTimeSame'])assert.equal(same[field],true,field);
 assert.ok(same.currentTimeAfter>=same.currentTimeBefore);assert.equal(same.event.changed,false);assert.equal(same.event.recovered,false);
 report.cases.push({name:'Unchanged natural HTTP manual refresh preserves DOM, focus and live lighting clock',status:'passed',measured:same});
 const changed=JSON.parse(JSON.stringify(snapshot)),gameId='2026_04_DAL_HOU';
 for(const t of Object.values(changed.teams)){const g=t.games.find(g=>g.id===gameId);if(g){g.stats.DAL.rushing+=1;g.stats.DAL.totalOffense+=1;}}
 assert.equal(changed.retrievedAt,snapshot.retrievedAt);fixture(changed);await refreshNative();
 assert.deepEqual(await page.evaluate(()=>window.PDTeamDetails.getDataset()),changed);
 assert.equal(await page.locator(`[data-team-game="${gameId}"]>span`).nth(3).innerText(),'400');
 const correction=await page.evaluate(()=>{const m=window.__pdRefreshFixtureAudit;return{heroChanged:m.hero!==m.root.querySelector('.td-hero'),event:m.events.at(-1)};});assert.equal(correction.heroChanged,true);assert.equal(correction.event.changed,true);
 report.cases.push({name:'Corrected football statistic with identical retrieval timestamp is applied and rendered',status:'passed',qualification:'Synthetic fixture only: rushing 75→76 and total offense399→400, original current facts unchanged.',measured:correction,retrievedAt:changed.retrievedAt});
 const older=JSON.parse(JSON.stringify(changed));older.retrievedAt=new Date(Date.parse(changed.retrievedAt)-1000).toISOString();fixture(older);await refreshNative();
 assert.deepEqual(await page.evaluate(()=>window.PDTeamDetails.getDataset()),changed);
 const olderText=await page.locator('[data-page="team-details"] .td-footer').innerText();assert.match(olderText,/UPDATE FAILED/);assert.match(olderText,/RETAINED VERIFIED DATA/);
 report.cases.push({name:'Older snapshot rejects refresh and retains last good fixture',status:'passed',error:olderText});
 fixture(changed);await refreshNative();const recoveredOlder=await page.evaluate(()=>window.__pdRefreshFixtureAudit.events.at(-1));assert.equal(recoveredOlder.changed,false);assert.equal(recoveredOlder.recovered,true);assert.doesNotMatch(await page.locator('[data-page="team-details"] .td-footer').innerText(),/UPDATE FAILED|RETAINED VERIFIED DATA/);
 report.cases.push({name:'Identical successful snapshot clears prior older-snapshot error',status:'passed',event:recoveredOlder});
 fixture(changed,503);await refreshNative(503);assert.deepEqual(await page.evaluate(()=>window.PDTeamDetails.getDataset()),changed);
 const unavailableText=await page.locator('[data-page="team-details"] .td-footer').innerText();assert.match(unavailableText,/UPDATE FAILED/);assert.match(unavailableText,/RETAINED VERIFIED DATA/);
 report.cases.push({name:'Natural HTTP503 retains the last good snapshot and shows the failure',status:'passed',error:unavailableText});
 fixture(changed);await refreshNative();assert.deepEqual(await page.evaluate(()=>window.PDTeamDetails.getDataset()),changed);const recovery=await page.evaluate(()=>window.__pdRefreshFixtureAudit.events.at(-1));assert.equal(recovery.changed,false);assert.equal(recovery.recovered,true);assert.doesNotMatch(await page.locator('[data-page="team-details"] .td-footer').innerText(),/UPDATE FAILED|RETAINED VERIFIED DATA/);
 report.cases.push({name:'Identical successful snapshot clears HTTP503 failure and emits recovery',status:'passed',event:recovery});
 assert.deepEqual(errors,[]);assert.deepEqual(failed,[]);assert.deepEqual(responseErrors,[{url:base+'assets/data/team-details.json',status:503}]);report.errors={javascript:errors,requestFailures:failed,expectedFixtureHTTP503:responseErrors};
 report.naturalHTTPRequests=fs.readFileSync(logFile,'utf8').trim().split('\n').map(s=>JSON.parse(s));assert.ok(report.naturalHTTPRequests.length>=7);
 assert.deepEqual(Q.runtimeManifest(),before);report.runtimeUnchanged=true;report.status='passed';await context.close();
}catch(e){report.status='failed';report.failure={message:e.message,stack:e.stack};}finally{
 if(browser)await browser.close();if(server){server.kill('SIGTERM');if(server.exitCode===null)await once(server,'exit');}
 report.completedAt=new Date().toISOString();report.runtimeUnchanged=JSON.stringify(Q.runtimeManifest())===JSON.stringify(before);
 fs.writeFileSync(ROOT+'/qa/team-details/reviews/sources/refresh-integration-audit.json',JSON.stringify(report,null,2)+'\n');
 console.log(JSON.stringify({status:report.status,cases:report.cases.length,runtimeUnchanged:report.runtimeUnchanged,failure:report.failure?.message}));process.exitCode=report.status==='passed'?0:1;
}})();
